module TopModule(
    input  [1023:0] in,
    input  [7:0] sel,
    output [3:0] out
);
    reg [3:0] outs [0:255];
    integer i;
    always @(*) begin
        for (i = 0; i < 256; i = i + 1)
            outs[i] = in[4 * i +: 4];
    end
    assign out = outs[sel];
endmodule

